<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue';import {pmsApi} from './api';import {withoutPmsLoader} from './loading';import PmsFormDialog from './PmsFormDialog.vue';
const props=defineProps<{id:number;csrf?:string}>();const emit=defineEmits(['close','transferred']);const projects=ref<any[]>([]),title=ref(''),error=ref(''),busy=ref(false),loading=ref(true),company=ref(''),client=ref('');let disposed=false;
const form=ref({project_id:'',department_id:'',sprint_id:'',reason:''});
const companies=computed(()=>Array.from(new Map(projects.value.filter(p=>p.company).map(p=>[p.company.id,p.company])).values()) as any[]);
const clients=computed(()=>Array.from(new Map(projects.value.filter(p=>p.client&&(!company.value||String(p.company_id)===company.value)).map(p=>[p.client.id,p.client])).values()) as any[]);
const matches=computed(()=>projects.value.filter(p=>(!company.value||String(p.company_id)===company.value)&&(!client.value||String(p.client_id)===client.value)));
const project=computed(()=>projects.value.find(p=>String(p.id)===String(form.value.project_id)));
const sprints=computed(()=>project.value?.sprints.filter((s:any)=>String(s.department_id)===String(form.value.department_id))||[]);
async function save(){busy.value=true;error.value='';try{const result=await pmsApi('tasks/'+props.id+'/transfer',props.csrf,'POST',{...form.value,sprint_id:form.value.sprint_id||null});emit('transferred',result);}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(async()=>{try{const d=await withoutPmsLoader(()=>pmsApi('tasks/'+props.id+'/transfer'));if(!disposed){projects.value=d.projects;title.value=d.task.title;}}catch(e){if(!disposed)error.value=(e as Error).message;}finally{loading.value=false;}});onUnmounted(()=>{disposed=true;});
</script>
<template><PmsFormDialog title="Transfer task" :subtitle="title" centered @close="!busy&&emit('close')"><form class="pms-reference-form" @submit.prevent="save"><p v-if="error" class="notice admin-error full-width" role="alert">{{error}}</p><p class="text-muted full-width">Comments, files, subtasks, and logged time stay with this task. Assignees without access to the destination company will be removed. Running timers must be stopped first.</p><label>Company<select v-model="company" :disabled="loading||busy" @change="client='';form.project_id='';form.department_id='';form.sprint_id=''"><option value="">All accessible companies</option><option v-for="c in companies" :key="c.id" :value="String(c.id)">{{c.name}}</option></select></label><label>Client<select v-model="client" :disabled="loading||busy" @change="form.project_id='';form.department_id='';form.sprint_id=''"><option value="">All accessible clients</option><option v-for="c in clients" :key="c.id" :value="String(c.id)">{{c.name}}</option></select></label><label class="full-width">Destination project<select v-model="form.project_id" required :disabled="loading||busy" @change="form.department_id='';form.sprint_id=''"><option disabled value="">Select project</option><option v-for="p in matches" :key="p.id" :value="String(p.id)">{{p.name}}</option></select></label><label>Department<select v-model="form.department_id" required :disabled="!project||busy" @change="form.sprint_id=''"><option disabled value="">Select department</option><option v-for="d in project?.departments" :key="d.id" :value="String(d.id)">{{d.dept_name}}</option></select></label><label>Sprint<select v-model="form.sprint_id" :disabled="!form.department_id||busy"><option value="">Backlog</option><option v-for="s in sprints" :key="s.id" :value="String(s.id)">{{s.name}}</option></select></label><label class="full-width">Reason<textarea v-model="form.reason" maxlength="2000" rows="3" placeholder="Explain why the task is moving"></textarea></label><div class="editor-actions"><button type="button" class="button" :disabled="busy" @click="emit('close')">Cancel</button><button class="button primary" :disabled="busy||loading||!form.project_id||!form.department_id">Transfer task</button></div></form></PmsFormDialog></template>
